&lt;/a&gt;&lt;table id=&quot;TocContainerTable&quot;&gt;&lt;tr&gt;&lt;td&gt;&lt;div id=&quot;TocContainer&quot;&gt;&lt;p class=&quot;small&quot;&gt;&lt;b&gt;Table of Contents&lt;/b&gt;&lt;span id=&quot;ExpandTocSpan&quot;&gt; [&lt;a href=&quot;#&quot; onclick=&quot;javascript:if(document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]==&#39;none&#39;) document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;&#39;; else document.getElementById(&#39;Toc&#39;).style[&#39;display&#39;]=&#39;none&#39;; return false;&quot;&gt;Hide/Show&lt;/a&gt;]&lt;/span&gt;&lt;/p&gt;&lt;div id=&quot;Toc&quot;&gt;&lt;p&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Modifications_des_comp&#233;tences_12&quot;&gt;Modifications des comp&#233;tences&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Acquisition_des_comp&#233;tences_daventure_13&quot;&gt;Acquisition des comp&#233;tences d&#39;aventure&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Acquisition_des_comp&#233;tences_contextuelles_14&quot;&gt;Acquisition des comp&#233;tences contextuelles&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Comp&#233;tences_de_classe_5&quot;&gt;Comp&#233;tences de classe&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Conversion_des_personnages_6&quot;&gt;Conversion des personnages&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Monstres_et_PNJ_15&quot;&gt;Monstres et PNJ&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Nouvelles_comp&#233;tences_16&quot;&gt;Nouvelles comp&#233;tences&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Cr&#233;ation_artistique_Int_7&quot;&gt;Cr&#233;ation artistique (Int)&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Test_de_comp&#233;tence__0&quot;&gt; Test de comp&#233;tence &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Action__1&quot;&gt; Action &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Nouvelles_tentatives__2&quot;&gt; Nouvelles tentatives &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Savoir_Int_formation_n&#233;cessaire_8&quot;&gt;Savoir (Int, formation n&#233;cessaire)&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Test_de_comp&#233;tence__3&quot;&gt; Test de comp&#233;tence &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Bardes__4&quot;&gt; Bardes &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Utilisations_&#233;tendues_des_comp&#233;tences_17&quot;&gt;Utilisations &#233;tendues des comp&#233;tences&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Artisanat_&#233;tendu_9&quot;&gt;Artisanat &#233;tendu&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Profession_&#233;tendue_10&quot;&gt;Profession &#233;tendue&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Repr&#233;sentation_&#233;tendue_11&quot;&gt;Repr&#233;sentation &#233;tendue&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;Le syst&#232;me de comp&#233;tences d&#233;crit dans le Manuel des Joueurs est tr&#232;s polyvalent. Il permet aux personnages de surmonter diverses &#233;preuves gr&#226;ce &#224; leurs talents vari&#233;s en appliquant des r&#232;gles simples qui prennent en compte les conditions avantageuses ou d&#233;savantageuses. Beaucoup de joueurs investissent simplement leurs rangs dans les m&#234;mes comp&#233;tences &#224; chaque niveau, mais un personnage peut tout &#224; fait diversifier cet investissement afin d’avoir acc&#232;s &#224; davantage de comp&#233;tences ou pour rem&#233;dier &#224; un manque au sein de son groupe.&lt;br /&gt;&lt;br /&gt;Toutefois, les comp&#233;tences ne rev&#234;tent pas toutes la m&#234;me utilit&#233; pour les personnages. On peut difficilement affirmer qu’un bonus &#233;lev&#233; dans une comp&#233;tence de Profession a la m&#234;me valeur que ce m&#234;me bonus dans une comp&#233;tence plus g&#233;n&#233;rale comme Perception. Il n’emp&#234;che que &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; est une comp&#233;tence importante pour les personnages non-joueurs, tout comme pour les joueurs qui ne veulent pas faire de l’aventure le seul centre d’int&#233;r&#234;t de leurs personnages.&lt;br /&gt;&lt;br /&gt;Le syst&#232;me des comp&#233;tences contextuelles souligne l’importance des comp&#233;tences d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt;. M&#234;me si ces comp&#233;tences n’affectent pas directement la carri&#232;re d’aventuriers typiques de la m&#234;me fa&#231;on que le Bluff, la Perception et la Discr&#233;tion, elles restent des moyens utiles que les personnages peuvent exploiter pour interagir avec le monde et l’explorer en dehors des phases de combat. Vous ne devriez pas avoir &#224; choisir entre les connaissances pour comprendre le monde et les comp&#233;tences pour y survivre !&lt;br /&gt;&lt;br /&gt;On utilise le terme de comp&#233;tences contextuelles car elles refl&#232;tent les centres d’int&#233;r&#234;ts et les passions d’un personnage-joueur en dehors des aventures et parce qu’elles sont importantes pour les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt;. Toutes les autres comp&#233;tences sont des comp&#233;tences d’aventure.&lt;br /&gt;&lt;br /&gt;Dans les campagnes o&#249; l’on applique le syst&#232;me des comp&#233;tences contextuelles, chaque personnage dispose de 2 rangs de comp&#233;tences suppl&#233;mentaires par niveau, &#224; investir obligatoirement dans des comp&#233;tences contextuelles. Vous trouverez plus d’informations dans la section &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#ACQUISITIONDESCOMPETENCESCONTEXTUELLES&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Acquisition des comp&#233;tences contextuelles&lt;/a&gt;&quot;. Ces r&#232;gles nouvelles augmentent la polyvalence des personnages et de leurs comp&#233;tences. Toutefois, comme elles am&#233;liorent uniquement les comp&#233;tences utiles en dehors des aventures, elles ne risquent pas de d&#233;s&#233;quilibrer le jeu.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Modifications des comp&#233;tences&lt;a class=&quot;headeranchor&quot; id=&quot;Modifications_des_comp&#233;tences_12&quot; href=&quot;#Modifications_des_comp&#233;tences_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; et certaines &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; sp&#233;cialis&#233;es sont toutes des comp&#233;tences contextuelles. Alors que toutes ces comp&#233;tences peuvent s’av&#233;rer utiles, voire indispensables, dans certaines campagnes (comme Profession [marin] dans une campagne nautique) ou pour certains personnages (comme Dressage pour un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt;), leur utilit&#233; est souvent moins &#233;vidente dans l’imm&#233;diat, compar&#233; au fait de pouvoir frapper un adversaire dans le dos en utilisant la &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; ou de traverser des contr&#233;es sauvages en utilisant la &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Ce syst&#232;me ajoute &#233;galement deux nouvelles comp&#233;tences contextuelles : Cr&#233;ation artistique et Savoir. Comparable &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;, la comp&#233;tence de Cr&#233;ation artistique permet d’&#233;laborer une œuvre artistique qui n’est pas n&#233;cessairement un objet ou une repr&#233;sentation artistique. Cette comp&#233;tence peut servir &#224; composer une œuvre musicale ou une pi&#232;ce de th&#233;&#226;tre, des po&#232;mes et toutes sortes d’autres œuvres d’art. De son c&#244;t&#233;, le Savoir fonctionne comme une comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; particuli&#232;rement sp&#233;cialis&#233;e. Un personnage peut avoir Savoir (histoire elfique) sans &#234;tre form&#233; &#224; la comp&#233;tence plus g&#233;n&#233;raliste de Connaissances (histoire). De la m&#234;me fa&#231;on, il peut ma&#238;triser la comp&#233;tence de Savoir (chefs d’œuvre artistiques) sans avoir investi de rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt;, Cr&#233;ation artistique ou &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Vous trouverez la description des nouvelles comp&#233;tences dans la section &quot;&lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#NOUVELLESCOMPETENCES&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Nouvelles comp&#233;tences&lt;/a&gt;&quot;. Une section est consacr&#233;e &#224; chacune. Des sections &#233;tendues sont &#233;galement consacr&#233;es aux comp&#233;tences d&#233;j&#224; existantes d&#233;sormais consid&#233;r&#233;es comme des comp&#233;tences contextuelles.&lt;br /&gt;&lt;br /&gt;La table suivante donne la liste des comp&#233;tences nouvelles et red&#233;finies, ainsi que leur appartenance &#224; la cat&#233;gorie des comp&#233;tences d’aventure ou des comp&#233;tences contextuelles.&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;94%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Comp&#233;tences d&#39;aventure&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (exploration souterraine)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Premiers-Secours.html&quot; title=&quot;Premiers secours&quot;&gt;Premiers secours&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;UOM&quot;&gt;Utilisation d’objets magiques&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td width=&quot;50%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;94%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Comp&#233;tences contextuelles&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (ing&#233;nierie)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (noblesse)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#CREATIONARTISTIQUE&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Cr&#233;ation artistique&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#SAVOIR&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Savoir&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Acquisition des comp&#233;tences d&#39;aventure&lt;a class=&quot;headeranchor&quot; id=&quot;Acquisition_des_comp&#233;tences_daventure_13&quot; href=&quot;#Acquisition_des_comp&#233;tences_daventure_13&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les comp&#233;tences d’aventure sont les plus pertinentes et les plus utiles pour des personnages en cours d’aventure. Ils les acqui&#232;rent gr&#226;ce aux rangs de comp&#233;tence standards que toutes les classes de personnage re&#231;oivent, modifi&#233;s par leur &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; (et parfois par leur race et d’autres facteurs). Ces comp&#233;tences n’ont pas besoin d’&#234;tre ajust&#233;es si vous utilisez le syst&#232;me des comp&#233;tences contextuelles.&lt;br /&gt;&lt;br /&gt;La plupart des comp&#233;tences d’aventure sont li&#233;es &#224; l’entra&#238;nement et &#224; la pratique et chacune s’utilise de mani&#232;re claire et sp&#233;cifique pour surmonter les &#233;preuves rencontr&#233;es quotidiennement par un aventurier professionnel. La plupart des tests de comp&#233;tence effectu&#233;s en cours de jeu sont des tests de comp&#233;tences d’aventure, voil&#224; pourquoi un personnage devrait investir la majorit&#233; de ses rangs de comp&#233;tences dans celles-ci.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ACQUISITIONDESCOMPETENCESCONTEXTUELLES&quot; href=&quot;#ACQUISITIONDESCOMPETENCESCONTEXTUELLES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acquisition des comp&#233;tences contextuelles&lt;a class=&quot;headeranchor&quot; id=&quot;Acquisition_des_comp&#233;tences_contextuelles_14&quot; href=&quot;#Acquisition_des_comp&#233;tences_contextuelles_14&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;En plus du nombre normal de rangs de comp&#233;tence que les personnages obtiennent &#224; chaque fois qu’ils gagnent un niveau dans une classe de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt;, ils obtiennent &#233;galement deux rangs de comp&#233;tence contextuelle. Le modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; des personnages ne modifie pas cette valeur. Les rangs de comp&#233;tence contextuelle s’investissent uniquement dans les comp&#233;tences contextuelles et non dans les comp&#233;tences d’aventure tandis que les personnages peuvent investir leurs rangs de comp&#233;tence standards dans les comp&#233;tences contextuelles s’ils le souhaitent.&lt;br /&gt;&lt;br /&gt;M&#234;mes les aventuriers les plus d&#233;vou&#233;s &#224; leur t&#226;che aiment participer &#224; d’autres activit&#233;s lors de leur temps libre. Certains se lancent dans les affaires pendant leurs p&#233;riodes d’interm&#232;des entre chaque aventure. Les &lt;a class=&quot;pagelink&quot; href=&quot;Interm&#232;des.html&quot; title=&quot;Les interm&#232;des&quot;&gt;r&#232;gles d’interm&#232;des&lt;/a&gt; d&#233;crites dans le Guide de campagne Pathfinder JdR expliquent comment g&#233;rer ce type d’activit&#233;s, mais certains joueurs trouvent ce syst&#232;me trop imposant bien qu’ils d&#233;sirent tout de m&#234;me inclure certains aspects de ce genre d’activit&#233;s sur leur feuille de personnage.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_5&quot; href=&quot;#Comp&#233;tences_de_classe_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Si vous appliquez le syst&#232;me des comp&#233;tences contextuelles, les classes utilisent leur liste standard de comp&#233;tences de classe respective. Toutes les classes qui ont &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; en comp&#233;tence de classe consid&#232;rent &#233;galement &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#CREATIONARTISTIQUE&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Cr&#233;ation artistique&lt;/a&gt; comme une comp&#233;tence de classe. &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#SAVOIR&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Savoir&lt;/a&gt; est toujours consid&#233;r&#233; comme une comp&#233;tence de classe pour tous les personnages.&lt;br /&gt;&lt;br /&gt;Par exemple, la liste standard des comp&#233;tences de classe de &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; comporte la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt;. Ainsi, pour un magicien, la comp&#233;tence contextuelle d’Estimation est une comp&#233;tence de classe. &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; est &#233;galement sur sa liste de comp&#233;tences de classe et on consid&#232;re donc que &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#CREATIONARTISTIQUE&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Cr&#233;ation artistique&lt;/a&gt; est pour lui &#233;galement une comp&#233;tence de classe (m&#234;me si &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; n’apparait pas sur cette liste).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Conversion des personnages&lt;a class=&quot;headeranchor&quot; id=&quot;Conversion_des_personnages_6&quot; href=&quot;#Conversion_des_personnages_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Il est tr&#232;s facile d’int&#233;grer des comp&#233;tences contextuelles dans une campagne en cours. Pour convertir les rangs de comp&#233;tence d’un personnage &#224; ce syst&#232;me, il faut commencer par d&#233;terminer le nombre total de rangs de comp&#233;tence contextuelle qu’il poss&#232;de. Ce nombre est &#233;gal &#224; 2 &#215; le niveau de personnage du PJ. Ensuite, d&#233;terminez le nombre de rangs qu’il a d&#233;j&#224; investis dans les comp&#233;tences consid&#233;r&#233;es, d’apr&#232;s ce syst&#232;me, comme des comp&#233;tences contextuelles. Le personnage dispose de ce nombre de rangs de comp&#233;tence qu’il peut investir dans toutes les comp&#233;tences, ce qui permet de r&#233;cup&#233;rer les rangs de comp&#233;tence classique investis dans les comp&#233;tences contextuelles. Enfin, soustrayez ce nombre du nombre total de rangs de comp&#233;tence contextuelle du personnage pour d&#233;terminer le nombre de rangs de comp&#233;tence contextuelle qu’il peut encore investir. Par exemple, un &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; de niveau 5 dispose de 10 rangs de comp&#233;tence contextuelle. S’il a d&#233;j&#224; investi 5 rangs dans des comp&#233;tences d&#233;sormais consid&#233;r&#233;es comme contextuelles, il peut investir 5 rangs de comp&#233;tence contextuelle dans ces comp&#233;tences, ce qui lui lib&#232;re les 5 rangs initialement d&#233;pens&#233;s qu’il peut &#224; pr&#233;sent investir dans n’importe quelles comp&#233;tences. Il lui reste encore 5 rangs de comp&#233;tence contextuelle qu’il peut investir dans les comp&#233;tences de ce type.&lt;br /&gt;&lt;br /&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; peut autoriser une certaine dose de &lt;a class=&quot;pagelink&quot; href=&quot;Le-R&#233;apprentissage.html&quot; title=&quot;Le r&#233;apprentissage&quot;&gt;r&#233;apprentissage&lt;/a&gt; pour prendre en compte les nouvelles comp&#233;tences contextuelles. Un personnage qui a investi des rangs dans la comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (po&#232;te) peut vouloir investir ses rangs dans la comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#CREATIONARTISTIQUE&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Cr&#233;ation artistique&lt;/a&gt; (po&#233;sie) &#224; la place. De m&#234;me, un personnage qui a investi des rangs dans la comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie) pour expliquer le temps pass&#233; &#224; naviguer sur un fleuve particulier peut investir ces rangs dans la comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences-Contextuelles.html#SAVOIR&quot; title=&quot;Comp&#233;tences contextuelles&quot;&gt;Savoir&lt;/a&gt; de ce fleuve &#224; la place.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Monstres et PNJ&lt;a class=&quot;headeranchor&quot; id=&quot;Monstres_et_PNJ_15&quot; href=&quot;#Monstres_et_PNJ_15&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;En r&#232;gle g&#233;n&#233;rale, les monstres n’ont pas acc&#232;s aux comp&#233;tences contextuelles gr&#226;ce &#224; leurs &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;d&#233;s de vie&lt;/a&gt; raciaux. Le ma&#238;tre de jeu peut d&#233;cider que certains types de monstres s’adonnent depuis longtemps &#224; un type d’artisanat ou de profession (comme les &lt;a class=&quot;pagelink&quot; href=&quot;G&#233;ant-Des-Temp&#234;tes.html&quot; title=&quot;G&#233;ant, G&#233;ant des temp&#234;tes&quot;&gt;g&#233;ants des temp&#234;tes&lt;/a&gt;, par exemple) et qu’ils disposent donc de comp&#233;tences contextuelles, mais cette d&#233;cision est optionnelle.&lt;br /&gt;&lt;br /&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagenonjoueur.html&quot; title=&quot;PNJ&quot;&gt;PNJ&lt;/a&gt; obtiennent des comp&#233;tences contextuelles de la m&#234;me fa&#231;on que les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; mais seulement pour les classes de PJ qu’ils poss&#232;dent. Cette r&#232;gle s’applique &#233;galement aux monstres qui poss&#232;dent des niveaux dans des classes de PJ. Les PNJ n’ont pas &#224; d&#233;penser leurs rangs de comp&#233;tences contextuelles et ces comp&#233;tences affectent rarement les combats. Les personnages qui poss&#232;dent des classes de PNJ seulement, et plus particuli&#232;rement les &lt;a class=&quot;pagelink&quot; href=&quot;Noble.html&quot; title=&quot;Le noble&quot;&gt;nobles&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Du-Peuple.html&quot; title=&quot;L&amp;#39;homme du peuple&quot;&gt;hommes du peuple&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Expert.html&quot; title=&quot;L&amp;#39;expert&quot;&gt;experts&lt;/a&gt;, investissent souvent leurs rangs de comp&#233;tences d’aventure dans leurs comp&#233;tences contextuelles.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NOUVELLESCOMPETENCES&quot; href=&quot;#NOUVELLESCOMPETENCES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Nouvelles comp&#233;tences&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_comp&#233;tences_16&quot; href=&quot;#Nouvelles_comp&#233;tences_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Cette section vous pr&#233;sente deux nouvelles comp&#233;tences : Cr&#233;ation artistique et Savoir. M&#234;me si vous n’appliquez pas le syst&#232;me des comp&#233;tences contextuelles, vous pouvez toujours int&#233;grer ces comp&#233;tences dans vos parties en tant que comp&#233;tences classiques.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CREATIONARTISTIQUE&quot; href=&quot;#CREATIONARTISTIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Cr&#233;ation artistique (Int)&lt;a class=&quot;headeranchor&quot; id=&quot;Cr&#233;ation_artistique_Int_7&quot; href=&quot;#Cr&#233;ation_artistique_Int_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage ma&#238;trise les arts cr&#233;atifs et exploite son sens artistique pour donner vie aux merveilles de son imagination. Tout comme les diff&#233;rents &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanats&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentations&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Professions&lt;/a&gt;, Cr&#233;ation artistique englobe en r&#233;alit&#233; plusieurs comp&#233;tences distinctes. Le personnage peut ma&#238;triser plusieurs comp&#233;tences de Cr&#233;ation artistique, chacune avec ses propres rangs. Voici les comp&#233;tences de Cr&#233;ation artistique les plus courantes : chor&#233;graphie, composition musicale, critique, dramaturgie, litt&#233;rature (y compris la po&#233;sie) et philosophie.&lt;br /&gt;&lt;br /&gt;Comme l’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;, une comp&#233;tence de Cr&#233;ation artistique permet de cr&#233;er quelque chose. Toutefois, cette chose n’est pas n&#233;cessairement un objet physique. Ce peut &#234;tre le mod&#232;le ou le plan d’un objet ou une m&#233;thode plus efficace pour fabriquer un certain type d’objets. Ainsi, un test de Cr&#233;ation artistique (composition musicale) peut servir &#224; composer une nouvelle chanson, mais le fruit de l’acte de cr&#233;ation est la chanson elle-m&#234;me, pas le papier sur lequel elle est r&#233;dig&#233;e ni le fait de la chanter. Un artiste n’est pas n&#233;cessairement un interpr&#232;te, un chanteur ou un acteur comp&#233;tent, m&#234;me s’il peut l’&#234;tre &#233;galement. Il cherche plut&#244;t &#224; cr&#233;er des id&#233;es et des concepts et &#224; concr&#233;tiser ces id&#233;es de fa&#231;on &#224; en faire profiter autrui et &#224; contribuer au partage de la culture et des arts. Il est parfois difficile de dire si certaines formes artistiques (comme la peinture ou la sculpture) sont du domaine de l’Artisanat ou de la Cr&#233;ation artistique. C’est le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; qui d&#233;cide si certaines comp&#233;tences d’Artisanat se remplacent par des comp&#233;tences de Cr&#233;ation artistique.&lt;br /&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Test de comp&#233;tence&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Test_de_comp&#233;tence__0&quot; href=&quot;#_Test_de_comp&#233;tence__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Le personnage sait cr&#233;er des œuvres d’art et peut tenter de gagner sa vie en impressionnant des m&#233;c&#232;nes avec son talent et ses id&#233;es.&lt;br /&gt;&lt;br /&gt;&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;DD du test de Cr&#233;ation artistique&lt;/td&gt;&lt;td&gt;Qualit&#233; du travail&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;&lt;b&gt;Œuvre banale.&lt;/b&gt; Personne n’ach&#232;te l’œuvre originale du personnage, mais on lui propose quelques menus travaux li&#233; &#224; ses talents, qui consistent souvent &#224; r&#233;parer ou &#224; copier le travail de quelqu’un d’autre. Le personnage gagne 1d10 pc par jour.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;&lt;b&gt;Œuvre plaisante.&lt;/b&gt; Dans une cit&#233; florissante, le personnage trouve plusieurs clients d&#233;sireux d’acqu&#233;rir son œuvre. Il gagne 1d10 pa par jour.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;20&lt;/td&gt;&lt;td&gt;&lt;b&gt;Œuvre impressionnante.&lt;/b&gt; Dans une cit&#233; florissante, le personnage gagne 3d10 pa par jour et peut recevoir une commission artistique vers&#233;e par une personnalit&#233; publique ou un individu riche. C’est ainsi que commence &#224; se d&#233;velopper la r&#233;putation du personnage au niveau local.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;25&lt;/td&gt;&lt;td&gt;&lt;b&gt;Œuvre m&#233;morable.&lt;/b&gt; Dans une cit&#233; florissante, le personnage gagne 1d6 po par jour. Il peut attirer l’attention de m&#233;c&#232;nes fortun&#233;s et commence &#224; d&#233;velopper une r&#233;putation au niveau national.&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;30&lt;/td&gt;&lt;td&gt;&lt;b&gt;Chef d’œuvre.&lt;/b&gt; Dans une cit&#233; florissante, le personnage gagne 3d6 po par jour. Avec le temps, il peut attirer l’attention de m&#233;c&#232;nes &#233;trangers, voire d’entit&#233;s extraplanaires.&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;Puisque les œuvres d’art sont les produits de l’imagination, les outils de qualit&#233; sup&#233;rieure n’apportent aucun avantage &#224; leur cr&#233;ation.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 16px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Qualit&#233; de l&#39;œuvre&lt;/td&gt;&lt;td&gt;DD&lt;/td&gt;&lt;td&gt;Commission&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Œuvre banale&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;td&gt;1 pa&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Œuvre plaisante&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;td&gt;25 po (250 pa)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Œuvre impressionnante&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;td&gt;50 po (500 pa)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Œuvre m&#233;morable&lt;/td&gt;&lt;td&gt;25&lt;/td&gt;&lt;td&gt;100 po (1 000 pa)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Chef d’œuvre&lt;/td&gt;&lt;td&gt;30&lt;/td&gt;&lt;td&gt;200 po (2 000 pa)&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;/div&gt;&lt;/div&gt;&lt;i&gt;Cr&#233;ation d’une œuvre sur commande.&lt;/i&gt; Si le personnage cr&#233;e une œuvre particuli&#232;re command&#233;e par un client, d&#233;terminez la valeur de l’œuvre que le personnage souhaite cr&#233;er en consultant la table ci-dessous, puis suivez les &#233;tapes indiqu&#233;es. Le personnage doit avoir un client d&#233;sireux de verser le prix fix&#233; pour pouvoir cr&#233;er une œuvre sur commande. Le montant touch&#233; lorsque le personnage tente de gagner sa vie en utilisant Cr&#233;ation artistique provient d’œuvres massivement distribu&#233;es ou publi&#233;es, pas d’une commande achet&#233;e par un unique client.&lt;br /&gt;&lt;br /&gt;Pour d&#233;terminer la dur&#233;e du travail et le co&#251;t investi pour cr&#233;er l’œuvre d’art, suivez ces &#233;tapes.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Premi&#232;re &#233;tape.&lt;/b&gt; D&#233;finissez le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; et le prix qui correspondent &#224; la qualit&#233; de l’œuvre que le personnage a l’intention de cr&#233;er.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;Deuxi&#232;me &#233;tape.&lt;/b&gt; Versez un quart du prix de l’œuvre que le personnage a l’intention de cr&#233;er. Ce co&#251;t repr&#233;sente l’achat de produits tels que des parchemins et de l’encre, l’embauche temporaire de musiciens, l’achat de mat&#233;riaux de recherche et autres &#233;l&#233;ments similaires.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;Troisi&#232;me &#233;tape.&lt;/b&gt; Le personnage effectue un test de Cr&#233;ation artistique contre le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; appropri&#233;. Ce test repr&#233;sente une semaine de travail. S’il le r&#233;ussit, multipliez le r&#233;sultat du test par le DD. Si la valeur obtenue est &#233;gale au prix de l’objet en pa, le personnage a termin&#233; l’œuvre d’art et touche sa commission (si la valeur obtenue est le double ou le triple du prix de l’œuvre en pi&#232;ces d’argent, le personnage a accompli la t&#226;che en deux ou trois fois moins de temps. De la m&#234;me fa&#231;on, les autres multiples du DD r&#233;duisent encore davantage le temps consacr&#233; &#224; la cr&#233;ation). Si la valeur obtenue n’&#233;gale pas le prix, elle repr&#233;sente les progr&#232;s accomplis pour la semaine, exprim&#233;s en pa. Si le test rate, le personnage ne progresse pas dans son travail.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;Quatri&#232;me &#233;tape.&lt;/b&gt; Si le personnage n’a pas termin&#233; son œuvre, il peut continuer &#224; travailler ou estimer qu’elle est termin&#233;e afin de limiter ses pertes. S’il persiste, il doit d&#233;penser un quart du prix &#224; nouveau pour chaque semaine de travail. Notez le r&#233;sultat du test obtenu lors de la premi&#232;re semaine et ajoutez les r&#233;sultats obtenus lors des semaines suivantes jusqu’&#224; ce que le total soit suffisant pour terminer l’œuvre ou que le personnage d&#233;cide d’arr&#234;ter pour limiter les pertes. S’il d&#233;cide d’arr&#234;ter, il gagne une commission &#233;quivalente &#224; la qualit&#233; de l’œuvre obtenue gr&#226;ce &#224; son total. Par exemple, si le personnage tente de cr&#233;er une œuvre m&#233;morable (pour une commission de 1 000 pa) et n’obtient que 600 pa de progr&#232;s, il peut d&#233;cider d’arr&#234;ter pour limiter ses pertes afin d’empocher une commission &#233;quivalent &#224; une œuvre impressionnante (500 pa ou 50 po). Le personnage ne peut pas toucher la commission d’une œuvre dont la qualit&#233; est sup&#233;rieure &#224; celle qu’il avait l’intention de cr&#233;er. Par cons&#233;quent, si le personnage avait l’intention de cr&#233;er une œuvre m&#233;morable mais r&#233;ussit un chef d’œuvre, il ne peut pas empocher une commission sup&#233;rieure &#224; 100 po. Quand il d&#233;cide de limiter les pertes, il ne r&#233;cup&#232;re pas l’argent investi en mat&#233;riaux et services. Par cons&#233;quent, s’il a d&#233;pens&#233; 250 pa en essayant de cr&#233;er une œuvre m&#233;morable, la vente d’une œuvre impressionnante lui rapporte un total de 250 pa seulement s’il a consacr&#233; une semaine de travail &#224; sa cr&#233;ation et il rembourse simplement ses frais si deux semaines de travail &#233;taient n&#233;cessaires. Il est possible de perdre de l’argent en travaillant sur une commande.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Action&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Action__1&quot; href=&quot;#_Action__1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Variable. La cr&#233;ation d’œuvres mineures pour gagner de l’argent n&#233;cessite g&#233;n&#233;ralement une semaine de travail. Si le personnage travaille moins d’une semaine, il gagne le montant moyen quotidien correspondant &#224; la qualit&#233; de l’œuvre obtenue. La cr&#233;ation d’une commande n&#233;cessite g&#233;n&#233;ralement une ou plusieurs semaines de travail.&lt;br /&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Nouvelles tentatives&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Nouvelles_tentatives__2&quot; href=&quot;#_Nouvelles_tentatives__2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Oui. Les nouvelles tentatives sont permises mais elles n’annulent pas les &#233;checs pr&#233;c&#233;dents. Si le personnage tente de gagner sa vie en tant qu’artiste dans une cit&#233; o&#249; le public n’a pas &#233;t&#233; impressionn&#233; par son œuvre (parce qu’il a rat&#233; un test de Cr&#233;ation artistique &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 15 lors de la semaine pr&#233;c&#233;dente), les chances de percer sur le march&#233; gr&#226;ce aux œuvres suivantes sont plus minces (le DD augmente de 2 pour chaque &#233;chec pr&#233;c&#233;dent). Si le personnage quitte les lieux pendant un mois ou plus avant de tenter &#224; nouveau sa chance, les &#233;ventuelles augmentations de DD engendr&#233;es par les &#233;checs pr&#233;c&#233;dents reviennent &#224; 0.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SAVOIR&quot; href=&quot;#SAVOIR&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Savoir (Int, formation n&#233;cessaire)&lt;a class=&quot;headeranchor&quot; id=&quot;Savoir_Int_formation_n&#233;cessaire_8&quot; href=&quot;#Savoir_Int_formation_n&#233;cessaire_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 16px 16px&quot;&gt;
&lt;div style=&quot;border: 1px solid #4b3124; padding: 4px&quot;&gt;
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Savoirs appropri&#233;s&lt;/td&gt;&lt;td&gt;Savoirs inappropri&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Une petite ville en particulier (ou&lt;br /&gt;une communaut&#233; encore plus petite)&lt;/td&gt;&lt;td&gt;Communaut&#233;s&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Un quartier d’une grande ville&lt;br /&gt;ou d’une m&#233;tropole&lt;/td&gt;&lt;td&gt;Une grande ville ou une&lt;br /&gt;m&#233;tropole dans sa totalit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Un monast&#232;re pr&#233;cis&lt;/td&gt;&lt;td&gt;Monast&#232;res&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Les tavernes d’une r&#233;gion&lt;/td&gt;&lt;td&gt;Tavernes&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Les bandits d’une r&#233;gion&lt;/td&gt;&lt;td&gt;Banditisme&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Les grandes batailles qui se sont&lt;br /&gt;d&#233;roul&#233;es dans une r&#233;gion&lt;/td&gt;&lt;td&gt;Grandes batailles&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Commerce des &#233;pices&lt;/td&gt;&lt;td&gt;Commerce&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Chats&lt;/td&gt;&lt;td&gt;Animaux&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Matriarches drows&lt;/td&gt;&lt;td&gt;Drows&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Histoire des nains&lt;/td&gt;&lt;td&gt;Nains&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;G&#233;ants du froid&lt;/td&gt;&lt;td&gt;G&#233;ants&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Sarenrae&lt;/td&gt;&lt;td&gt;Dieux&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Dagon&lt;/td&gt;&lt;td&gt;Seigneurs d&#233;mons&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Phl&#233;g&#233;thon&lt;/td&gt;&lt;td&gt;Enfers&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Commandants militaires&lt;/td&gt;&lt;td&gt;Guerre&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Chanteurs connus&lt;/td&gt;&lt;td&gt;Musique&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Contrats infernaux&lt;/td&gt;&lt;td&gt;Diables&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Sorts d’&#233;vocation&lt;/td&gt;&lt;td&gt;Sorts&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Argent et mithral&lt;/td&gt;&lt;td&gt;M&#233;taux&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Th&#233;&lt;/td&gt;&lt;td&gt;Boissons&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Arbres&lt;/td&gt;&lt;td&gt;Flore&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Tatouages&lt;/td&gt;&lt;td&gt;Art&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;&lt;/div&gt;&lt;/div&gt;Le personnage est vers&#233; dans un domaine de connaissances sp&#233;cialis&#233; et souvent moins &#233;tendu que celui d’un &#233;rudit accompli. Le Savoir est une comp&#233;tence fourre-tout qui permet d’obtenir des informations et qui fonctionne de mani&#232;re similaire &#224; celle d’Artisanat pour les diverses comp&#233;tences artisanales et &#224; celle de Profession pour les diverses comp&#233;tences professionnelles.&lt;br /&gt;&lt;br /&gt;Les cat&#233;gories d’une comp&#233;tence de Savoir varient grandement. Il peut s’agir d’un Savoir sur une r&#233;gion (telle qu’une cit&#233; ou un pays), sur une discipline (telle que la cryptographie) ou sur un petit groupe de personnes (comme les musiciens c&#233;l&#232;bres). Les comp&#233;tences de Savoir bas&#233;es sur une r&#233;gion peuvent &#233;galement faire r&#233;f&#233;rence &#224; des sous-cat&#233;gories particuli&#232;res, comme les tavernes d’une r&#233;gion en particulier.&lt;br /&gt;&lt;br /&gt;Une comp&#233;tence de Savoir doit se limiter &#224; un domaine tr&#232;s particulier, bien plus pointu que la comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; qui s’en rapproche. Plus le sujet du Savoir est vaste, plus les connaissances du personnage sont superficielles. Si le personnage connait les tavernes d’une vaste r&#233;gion, les informations sur chacune seront moins pr&#233;cises que celles d’un personnage qui poss&#232;de la comp&#233;tence de Savoir sur les tavernes d’une cit&#233; sp&#233;cifique. Les comp&#233;tences de Savoir ne servent g&#233;n&#233;ralement pas &#224; identifier des monstres comme les comp&#233;tences de Connaissances, &#224; moins qu’elles fassent directement r&#233;f&#233;rence &#224; un type particulier de monstres (les ours-hiboux ou les vampires, par exemple). Si la comp&#233;tence de Savoir concerne une race ou une cat&#233;gorie de monstres trop vaste ou trop courante, il est n&#233;cessaire de pr&#233;ciser cette cat&#233;gorie en la restreignant. La comp&#233;tence Savoir (elfes) est trop vaste, tout comme celle de Savoir (dragons).&lt;br /&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Test de comp&#233;tence&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Test_de_comp&#233;tence__3&quot; href=&quot;#_Test_de_comp&#233;tence__3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Les comp&#233;tences de Savoir utilisent la m&#234;me &#233;chelle de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; que les &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; : DD 10 pour r&#233;pondre &#224; des questions basiques, DD 15 pour r&#233;pondre &#224; des questions simples et DD 20, voire 30, pour des questions difficiles ou tr&#232;s difficiles. Dans de nombreux cas, le Savoir peut se substituer &#224; une comp&#233;tence de Connaissances, comme Savoir (histoire elfique) qui suppl&#233;e Connaissances (histoire) dans le cas d’un test &#224; propos des elfes. &#192; l’appr&#233;ciation du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, un joueur peut se servir d’une comp&#233;tence de Savoir partiellement li&#233;e &#224; un sujet en subissant un malus de -5. Ce sera le cas quand, par exemple, on se sert d’une comp&#233;tence de Savoir &#224; propos d’une r&#233;gion pour obtenir des informations sur une cit&#233; sp&#233;cifique de cette r&#233;gion ou quand on souhaite avoir des informations sur la vinification alors qu’on ma&#238;trise une comp&#233;tence de Savoir (distillation).&lt;br /&gt;&lt;br /&gt;La table ci-contre donne plusieurs exemples de comp&#233;tences de Savoir et de comp&#233;tences trop vagues. Cette liste n’est en aucun cas exhaustive et c’est au MJ de d&#233;cider de la pertinence d’une comp&#233;tence de Savoir particuli&#232;re.&lt;br /&gt;&lt;br /&gt;&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Bardes&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Bardes__4&quot; href=&quot;#_Bardes__4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;La comp&#233;tence de Savoir est consid&#233;r&#233;e comme une comp&#233;tence de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; dans le cadre des aptitudes de &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#SAVOIRBARDIQUE&quot; title=&quot;Le barde&quot;&gt;savoir bardique&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html#MAITREDUSAVOIR&quot; title=&quot;Le barde&quot;&gt;ma&#238;tre du savoir&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;bardes&lt;/a&gt;, ainsi que pour les aptitudes similaires d’autres classes, cr&#233;atures et arch&#233;types. Cette r&#232;gle s’applique uniquement aux comp&#233;tences de Savoir dans lesquelles le personnage a &#233;t&#233; form&#233;. Sinon, utilisez la comp&#233;tence de Connaissances la plus pertinente en fonction des questions pos&#233;es.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Utilisations &#233;tendues des comp&#233;tences&lt;a class=&quot;headeranchor&quot; id=&quot;Utilisations_&#233;tendues_des_comp&#233;tences_17&quot; href=&quot;#Utilisations_&#233;tendues_des_comp&#233;tences_17&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Des r&#232;gles basiques pour fabriquer des objets et gagner de l’argent gr&#226;ce aux comp&#233;tences d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; existent d&#233;j&#224;. Ceci dit, ces comp&#233;tences peuvent &#233;galement s’av&#233;rer utiles pour accomplir des t&#226;ches li&#233;es &#224; leur pratique. Vous trouverez dans cette section des exemples &#233;tendus d’utilisation avec les DD correspondants pour les t&#226;ches les plus courantes. Ces extensions proposent des m&#233;thodes d’utilisation suppl&#233;mentaires pour am&#233;liorer l’int&#233;gration de ces comp&#233;tences dans une session de jeu classique, utilisables m&#234;me sans appliquer le syst&#232;me des comp&#233;tences contextuelles. C’est le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; qui d&#233;cide de la pertinence de leur utilisation, surtout en ce qui concerne celles qui permettent &#224; un personnage d’en aider un autre en appliquant un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; inf&#233;rieur. Pour plus d’informations sur les sous-syst&#232;mes con&#231;us pour dupliquer la fabrication d’objets et pour g&#233;rer un commerce, voir les r&#232;gles d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat-Et-Profession-Alternatives.html&quot; title=&quot;Artisanat et Profession alternatives&quot;&gt;Artisanat et Profession alternatives&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Artisanat &#233;tendu&lt;a class=&quot;headeranchor&quot; id=&quot;Artisanat_&#233;tendu_9&quot; href=&quot;#Artisanat_&#233;tendu_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Il faut connaitre les propri&#233;t&#233;s et la qualit&#233; d’un objet pour savoir le fabriquer correctement. Certains de ces tests n&#233;cessitent une longue p&#233;riode de travail d&#233;finie par le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, surtout pour des t&#226;ches complexes comme la restauration d’une fresque. Cette section d&#233;crit &#233;galement deux comp&#233;tences d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; utiles qui n’apparaissent pas dans le Manuel des Joueurs : Artisanat (forge) et Artisanat (instruments de musique).&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;T&#226;che&lt;/td&gt;&lt;td&gt;Comp&#233;tence d’Artisanat&lt;/td&gt;&lt;td&gt;DD&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;D&#233;terminer de quelle culture un objet est issu (par ex., les elfes, les g&#233;ants du froid, etc.)&lt;/td&gt;&lt;td&gt;En fonction du type d’objet&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier la signature d’un artisan c&#233;l&#232;bre&lt;/td&gt;&lt;td&gt;En fonction du type d’objet&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier la signature d’un artisan m&#233;connu&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;En fonction du type d’objet&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier l’artisan &#224; l’origine d’un objet non sign&#233;&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;En fonction du type d’objet&lt;/td&gt;&lt;td&gt;30&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer la &lt;a class=&quot;pagelink&quot; href=&quot;Exploration#Solidite.html&quot; title=&quot;solidit&#233;&quot;&gt;solidit&#233;&lt;/a&gt; et les points de vie d’un objet&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;En fonction du type d’objet&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer les objets que peut fabriquer un &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; en examinant les substances pr&#233;sentes dans son laboratoire&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Alchimie&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Graver des motifs ornementaux sur les plates d’une armure m&#233;tallique&lt;/td&gt;&lt;td&gt;Armures ou peintures&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier une &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;armure de ma&#238;tre&lt;/a&gt; d’un simple coup d’œil&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer le type d’environnement dans lequel ont &#233;t&#233; pr&#233;lev&#233;s les mat&#233;riaux utilis&#233;s pour la confection d’un panier&lt;/td&gt;&lt;td&gt;Paniers&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer la r&#233;gion sp&#233;cifique dans laquelle ont &#233;t&#233; pr&#233;lev&#233;s les mat&#233;riaux utilis&#233;s pour la confection d’un panier&lt;/td&gt;&lt;td&gt;Paniers&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fondre du minerai et raffiner du m&#233;tal&lt;/td&gt;&lt;td&gt;Forge&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer des &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures#Pointespourarmure.html&quot; title=&quot;pointes pour armure (armure)&quot;&gt;pointes d’armure&lt;/a&gt; ou de bouclier sans utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (armures)&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Forge&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer l’anciennet&#233; approximative d’un livre&lt;/td&gt;&lt;td&gt;Livres&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier un &lt;a class=&quot;pagelink&quot; href=&quot;Arc-Long-Composite-(Arme).html&quot; title=&quot;Arc long composite&quot;&gt;arc composite&lt;/a&gt; d’un simple coup d’œil&lt;/td&gt;&lt;td&gt;Arcs&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier un arc &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armesmaitre.html&quot; title=&quot;arme de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; d’un simple coup d’œil&lt;/td&gt;&lt;td&gt;Arcs&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer le niveau d’exp&#233;rience d’un &#233;crivain et s’il &#233;crit de la main gauche ou droite&lt;/td&gt;&lt;td&gt;Calligraphie&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;R&#233;diger une invitation r&#233;pondant aux conventions sociales&lt;/td&gt;&lt;td&gt;Calligraphie&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer un tonneau ou une caisse&lt;/td&gt;&lt;td&gt;Constructions en bois&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer un radeau rudimentaire avec des mat&#233;riaux de r&#233;cup&#233;ration&lt;/td&gt;&lt;td&gt;Constructions en bois ou navires&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Sculpter un joli objet dans du bois&lt;/td&gt;&lt;td&gt;Charpenterie ou sculpture&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer une &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Bois-(Armure).html&quot; title=&quot;Armure de bois&quot;&gt;armure de bois&lt;/a&gt; ou un bouclier en bois sans utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (armures)&lt;/td&gt;&lt;td&gt;Charpenterie&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Teinter correctement un v&#234;tement ou un rouleau de tissu&lt;/td&gt;&lt;td&gt;&#201;toffes&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Raccommoder une voile&lt;/td&gt;&lt;td&gt;&#201;toffes, v&#234;tements, navires&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td width=&quot;50%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;tr&gt;&lt;td&gt;Modifier la taille ou la forme d’un v&#234;tement&lt;/td&gt;&lt;td&gt;V&#234;tements&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Confectionner une tenue temporaire adapt&#233;e au froid (conf&#232;re un bonus de +2)&lt;/td&gt;&lt;td&gt;V&#234;tements&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Confectionner une &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Matelass&#233;e-(Armure).html&quot; title=&quot;Armure matelass&#233;e&quot;&gt;armure matelass&#233;e&lt;/a&gt; sans utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (armures)&lt;/td&gt;&lt;td&gt;V&#234;tements&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Localiser ou identifier des formations de verre naturelles&lt;/td&gt;&lt;td&gt;Travail du verre&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier le travail des joailliers connus&lt;/td&gt;&lt;td&gt;Bijoux&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Tailler une fausse pierre pr&#233;cieuse&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Bijoux&lt;/td&gt;&lt;td&gt;Oppos&#233;&lt;sup&gt;2&lt;/sup&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier le type de cr&#233;ature sur laquelle a &#233;t&#233; pr&#233;lev&#233; le cuir utilis&#233; pour fabriquer un objet&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Travail du cuir&lt;/td&gt;&lt;td&gt;10&lt;sup&gt;3&lt;/sup&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&#201;corcher un animal et tanner sa peau&lt;/td&gt;&lt;td&gt;Travail du cuir&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer un objet de qualit&#233; &#224; partir du cuir d’une cr&#233;ature inhabituelle&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Travail du cuir&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer une &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-Clout&#233;e-(Armure).html&quot; title=&quot;Armure de cuir clout&#233;e&quot;&gt;de cuir clout&#233;e&lt;/a&gt;, ou &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures#Armuredepeau.html&quot; title=&quot;armure de peau (armure)&quot;&gt;de peau&lt;/a&gt; sans utiliser &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (armures)&lt;/td&gt;&lt;td&gt;Travail du cuir&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Aider quelqu’un qui effectue un test de &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; pour crocheter une serrure&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Serrures&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Accorder un instrument de musique&lt;/td&gt;&lt;td&gt;Instruments de musique&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer des peintures et autres pigments &#224; partir de rien&lt;/td&gt;&lt;td&gt;Peintures&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Peindre le portrait d’un individu de m&#233;moire&lt;/td&gt;&lt;td&gt;Peintures&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Peindre le portrait d’un individu gr&#226;ce &#224; la description d’un t&#233;moin oculaire&lt;/td&gt;&lt;td&gt;Peintures&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer un four &#224; poterie de fortune ou temporaire&lt;/td&gt;&lt;td&gt;Poteries&lt;/td&gt;&lt;td&gt;20&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer le moule d’un objet ou d’un morceau de corps&lt;/td&gt;&lt;td&gt;Sculpture&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Modifier la taille ou la forme de souliers&lt;sup&gt;1&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Souliers&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Reconna&#238;tre un navire connu et sa provenance probable&lt;/td&gt;&lt;td&gt;Navires&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Savoir si un mur est enti&#232;rement compos&#233; de pierre ou si celle-ci n’est qu’un simple rev&#234;tement&lt;/td&gt;&lt;td&gt;Constructions en pierre&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Fabriquer un support de pierre temporaire ou un petit rempart avec des mat&#233;riaux de r&#233;cup&#233;ration&lt;/td&gt;&lt;td&gt;Constructions en pierre&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;D&#233;terminer l’anciennet&#233; d’un pi&#232;ge m&#233;canique&lt;/td&gt;&lt;td&gt;Pi&#232;ges&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Identifier une arme de ma&#238;tre d’un simple coup d’œil&lt;/td&gt;&lt;td&gt;Armes&lt;/td&gt;&lt;td&gt;15&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td | COLSPAN=&quot;3&quot;&gt;&lt;i&gt;(1) Un personnage doit &#234;tre form&#233; dans la comp&#233;tence indiqu&#233;e pour tenter cette t&#226;che.&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td | COLSPAN=&quot;3&quot;&gt;&lt;i&gt;(2) Un personnage d&#233;tecte la supercherie en r&#233;ussissant un test oppos&#233; de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; ou d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (bijoux).&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td | COLSPAN=&quot;3&quot;&gt;&lt;i&gt;(3) Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; indiqu&#233; convient pour les objets fabriqu&#233;s &#224; partir du cuir d’animaux ordinaires, comme celui du b&#233;tail. Il augmente de 5 pour d’autres types de cr&#233;atures.&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;La table ci-dessous pr&#233;cise les comp&#233;tences d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; &#224; utiliser pour fabriquer des objets et des accessoires d’aventure essentiels. Cette liste ne pr&#233;cise pas les objets &#233;vidents : on fabrique des &lt;a class=&quot;pagelink&quot; href=&quot;V&#234;tements.html&quot; title=&quot;V&#234;tements&quot;&gt;tenues&lt;/a&gt; avec &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (v&#234;tements), des bateaux &#224; quille avec &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (navires), etc. On peut aussi utiliser des comp&#233;tences plus sp&#233;cifiques au lieu de celles indiqu&#233;es, comme &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (tatouages) au lieu d’&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (peintures) pour dessiner un &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Tatouage&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;tatouage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot; WIDTH=&quot;96%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;T&#226;che&lt;/td&gt;&lt;td&gt;Comp&#233;tence d’Artisanat&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animaux,-Montures-Et-Leur-&#201;quipement.html#Barde&quot; title=&quot;Animaux, montures et leur &#233;quipement&quot;&gt;Armures pour animaux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Armures&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Cha&#238;ne (3 m)&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;Cha&#238;ne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Forge ou pi&#232;ges&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moyens-De-Transport.html#Charrette&quot; title=&quot;Moyens de transport&quot;&gt;Charrette&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Moyens-De-Transport.html#Diligence&quot; title=&quot;Moyens de transport&quot;&gt;diligence&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Constructions en bois&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Chausse-trappes&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;Chausse-trappes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Armes&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Chevali&#232;re&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;Chevali&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Bijoux&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Coffre&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;Coffre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Constructions en bois ou serrures&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-Daventurier.html#Corde&quot;